// From the dashboard (POST /api/conversations/:id/whatsapp), after it has
// checked the signed-in team member belongs to this agency and has taken the
// conversation over: { tenant_id, conversation_id, content }.
const body = $input.first().json.body || {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
for (const f of ['tenant_id', 'conversation_id']) {
  if (!body[f] || !uuid.test(String(body[f]))) throw new Error(`${f} is required and must be a uuid`);
}
const content = String(body.content || '').trim();
if (!content) throw new Error('content is required');
if (content.length > 4096) throw new Error('content is longer than WhatsApp allows (4096 characters)');
return [{ json: { tenant_id: String(body.tenant_id), conversation_id: String(body.conversation_id), content } }];

// One row when the conversation is this agency's WhatsApp chat, nothing
// otherwise ('Load Conversation' always outputs, so this sees {}).
// WhatsApp only accepts a free-form message within 24 hours of the client's
// last message; after that it needs an approved template (not built), so
// it's refused here with a clear reason instead of failing at Meta.
const r = $input.first().json || {};
const input = $('Validate Input').first().json;
const fail = (code, error) => [{ json: { ok: false, code, error } }];

if (!r.conversation_id) return fail(404, 'This WhatsApp conversation was not found.');
if (!r.phone_number_id) {
  return fail(422, 'This agency has no WhatsApp number set up yet. Add the WhatsApp phone number id in Settings.');
}
const to = String(r.phone || '').replace(/\D/g, '');
if (to.length < 6) return fail(422, 'This contact has no WhatsApp number on file.');
const last = r.last_inbound_at ? new Date(r.last_inbound_at).getTime() : NaN;
if (!Number.isFinite(last) || Date.now() - last >= 24 * 3600e3) {
  return fail(409, "WhatsApp only allows replies within 24 hours of the client's last message. Wait for them to write again, or call or email them.");
}
return [{ json: { ok: true, to, phone_number_id: r.phone_number_id, text: input.content } }];

// Meta answers { messages: [{ id }] } when it accepted the message, or
// { error: { message, code } } when it didn't.
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const apiError = body && typeof body === 'object' ? body.error : null;
if (status >= 200 && status < 300 && !apiError) {
  const id = (body && body.messages && body.messages[0] && body.messages[0].id) || null;
  return [{ json: { code: 200, response: { success: true, wa_message_id: id } } }];
}
const reason = apiError
  ? `${apiError.message || 'unknown error'}${apiError.code ? ` (code ${apiError.code})` : ''}`
  : `HTTP ${status || 'no response'}`;
return [{ json: { code: 502, response: { success: false, error: `WhatsApp refused the message: ${reason}` } } }];
